local BookCoverInlayMaker = {}
local PRODUCTS = {
    iron_bookcoverinlay = { name = "Železni intarzija za naslovnice", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni intarzija za naslovnice za knjigoveze." },
    bronze_bookcoverinlay = { name = "Bronast intarzija za naslovnice", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast intarzija za naslovnice za knjigoveze." },
    silver_bookcoverinlay = { name = "Srebrn intarzija za naslovnice", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn intarzija za naslovnice za knjigoveze." },
    gilded_bookcoverinlay = { name = "Pozlačen intarzija za naslovnice", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen intarzija za naslovnice za knjigoveze." },
    jewel_set_bookcoverinlay = { name = "Draguljast intarzija za naslovnice", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast intarzija za naslovnice za knjigoveze." },
    royal_sovereign_bookcoverinlay = { name = "Kraljevski suveren intarzija za naslovnice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren intarzija za naslovnice z biseri za krono." },
}
local BUILDINGS = {
    bookcoverinlay_workshop = { name = "Bookcoverinlay delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookcoverinlay_house = { name = "Bookcoverinlay hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookcoverinlay_atelier = { name = "Mojstrski bookcoverinlay atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookcoverinlay_palace = { name = "Suverena bookcoverinlay palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookCoverInlayMaker.ironStock=12; BookCoverInlayMaker.bronzeStock=10; BookCoverInlayMaker.woodStock=14; BookCoverInlayMaker.leatherStock=10; BookCoverInlayMaker.silverStock=8; BookCoverInlayMaker.goldStock=6; BookCoverInlayMaker.jewelStock=4; BookCoverInlayMaker.pearlStock=4
BookCoverInlayMaker.productStock = {}; BookCoverInlayMaker.buildings = {}; BookCoverInlayMaker.maker = nil; BookCoverInlayMaker.activeMaking = {}; BookCoverInlayMaker.totalProducts = 0; BookCoverInlayMaker.dayTimer = 0
function BookCoverInlayMaker.init() BookCoverInlayMaker.ironStock=12; BookCoverInlayMaker.bronzeStock=10; BookCoverInlayMaker.woodStock=14; BookCoverInlayMaker.leatherStock=10; BookCoverInlayMaker.silverStock=8; BookCoverInlayMaker.goldStock=6; BookCoverInlayMaker.jewelStock=4; BookCoverInlayMaker.pearlStock=4; BookCoverInlayMaker.productStock={}; BookCoverInlayMaker.buildings={}; BookCoverInlayMaker.maker=nil; BookCoverInlayMaker.activeMaking={}; BookCoverInlayMaker.totalProducts=0; BookCoverInlayMaker.dayTimer=0; print("[BookCoverInlayMaker] Royal Book Cover Inlay Maker System initialized (6 products, 4 buildings)") end
function BookCoverInlayMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverInlayMaker.maker={name=n or ("Intarzist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Intarzist najet: %s (spretnost: %d)",BookCoverInlayMaker.maker.name,s),"success") end; return true end
function BookCoverInlayMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverInlayMaker.build(id) local ok,e=BookCoverInlayMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverInlayMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverInlayMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverInlayMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverInlayMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverInlayMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverInlayMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverInlayMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverInlayMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverInlayMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverInlayMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverInlayMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverInlayMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverInlayMaker.buildings==0 then return false,"Potrebna intarzijska delavnica" end; if not BookCoverInlayMaker.maker then return false,"Potreben intarzist" end; return true end
function BookCoverInlayMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverInlayMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverInlayMaker.ironStock=BookCoverInlayMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverInlayMaker.bronzeStock=BookCoverInlayMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverInlayMaker.woodStock=BookCoverInlayMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverInlayMaker.leatherStock=BookCoverInlayMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverInlayMaker.silverStock=BookCoverInlayMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverInlayMaker.goldStock=BookCoverInlayMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverInlayMaker.jewelStock=BookCoverInlayMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverInlayMaker.pearlStock=BookCoverInlayMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverInlayMaker.maker then t=math.max(1,t-math.floor(BookCoverInlayMaker.maker.skill/13)) end; table.insert(BookCoverInlayMaker.activeMaking,{id="bookcoverinlay_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverInlayMaker.completeMaking(m) local q=1.0+(BookCoverInlayMaker.getQualityBonus()/100); if BookCoverInlayMaker.maker then q=q+(BookCoverInlayMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverInlayMaker.productStock[m.productType]=(BookCoverInlayMaker.productStock[m.productType] or 0)+m.quantity; BookCoverInlayMaker.totalProducts=BookCoverInlayMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverInlayMaker.maker then BookCoverInlayMaker.maker.itemsMade=BookCoverInlayMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverInlayMaker.maker.skill=math.min(100,BookCoverInlayMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Intarzija izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverinlay.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverInlayMaker.update(dt) if not _G.state then return end; BookCoverInlayMaker.dayTimer=BookCoverInlayMaker.dayTimer+dt; if BookCoverInlayMaker.dayTimer>=30 then BookCoverInlayMaker.dayTimer=0; for i=#BookCoverInlayMaker.activeMaking,1,-1 do local m=BookCoverInlayMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverInlayMaker.completeMaking(m); table.remove(BookCoverInlayMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverInlayMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverInlayMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookCoverInlayMaker.getStats() return {ironStock=BookCoverInlayMaker.ironStock,bronzeStock=BookCoverInlayMaker.bronzeStock,woodStock=BookCoverInlayMaker.woodStock,leatherStock=BookCoverInlayMaker.leatherStock,silverStock=BookCoverInlayMaker.silverStock,goldStock=BookCoverInlayMaker.goldStock,jewelStock=BookCoverInlayMaker.jewelStock,pearlStock=BookCoverInlayMaker.pearlStock,productStock=BookCoverInlayMaker.productStock,numBuildings=#BookCoverInlayMaker.buildings,hasMaker=BookCoverInlayMaker.maker~=nil,makerName=BookCoverInlayMaker.maker and BookCoverInlayMaker.maker.name or "—",makerSkill=BookCoverInlayMaker.maker and BookCoverInlayMaker.maker.skill or 0,activeMaking=#BookCoverInlayMaker.activeMaking,totalProducts=BookCoverInlayMaker.totalProducts} end
return BookCoverInlayMaker
